<?php
add_action('template_redirect',function(){if(!isset($_GET['ngcd_baseline']))return;if(!current_user_can('manage_woocommerce'))wp_die('Access denied');$response=NGCD_API::snapshot();$data=$response->get_data();?><!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Commerce comparison baseline</title><style>body{margin:0;background:#f5f7fb;color:#17243a;font:16px/1.65 Arial,sans-serif}header{background:white;padding:25px 40px;border-bottom:1px solid #dde4ef}header small{color:#56647a;font-size:12px;display:block}main{padding:30px 40px}h1{font-size:30px;margin:8px 0}p{color:#56647a;max-width:850px}section{background:white;border:1px solid #dde4ef;border-radius:12px;margin-top:25px;padding:24px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:11px;border-bottom:1px solid #eceef4;text-align:left}th{color:#56647a;font-weight:500}h2{font-size:19px}.label{background:#f0eefc;color:#5b4fe8;padding:12px;font-size:12px}footer{padding:24px 40px;font-size:12px;color:#56647a} @media(max-width:600px){main{padding:20px}table{font-size:11px}th,td{padding:8px}section{padding:14px}header{padding:20px}}</style></head><body><header><strong>Forma Demo Store / data-only baseline</strong><small>Controlled comparison fixture, not the standard WooCommerce admin interface.</small></header><div class="label">SAME SYNTHETIC WOOCOMMERCE DATA · NO REAL STORE RESULTS</div><main><h1>Orders and inventory in separate lists.</h1><p>This intentionally simple baseline shows the data before adding the Commerce Desk operations interface. It is not a claim that WooCommerce lacks analytics, stock management or order tools.</p><section><h2>Orders</h2><table><thead><tr><th>Order</th><th>Fictional customer</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach(array_slice($data['orders'],0,7) as $o){echo '<tr><td>#'.esc_html($o['id']).'</td><td>'.esc_html($o['customer']).'</td><td>'.esc_html($o['status']).'</td><td>$'.esc_html(number_format($o['total'],2)).'</td></tr>';}?></tbody></table></section><section><h2>Inventory</h2><table><thead><tr><th>Product</th><th>SKU</th><th>Stock</th></tr></thead><tbody><?php foreach(array_slice($data['products'],0,5) as $p){echo '<tr><td>'.esc_html($p['name']).'</td><td>'.esc_html($p['sku']).'</td><td>'.esc_html($p['stock']).'</td></tr>';}?></tbody></table></section></main><footer>Fictional data. Controlled baseline, not a real client before/after. No measured sales or speed uplift.</footer></body></html><?php exit;},1);
